import java.util.*;

public class E {
    private static final int INFINITY = 1000000000;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        if (n > m) {
            int temp = n;
            n = m;
            m = temp;
        }

        int size = 1 << n;
        int[][] dp = new int[size][size];
        for (int[] row : dp) {
            Arrays.fill(row, INFINITY);
        }
        Arrays.fill(dp[0], 0);

        for (int step = 0; step < m; step++) {
            int[][] nextStates = new int[size][size];
            for (int[] row : nextStates) {
                Arrays.fill(row, INFINITY);
            }
            for (int prevMask = 0; prevMask < size; prevMask++) {
                for (int currMask = 0; currMask < size; currMask++) {
                    if (dp[prevMask][currMask] != INFINITY) {
                        int limit = (step == m - 1) ? 1 : size;
                        for (int nextMask = 0; nextMask < limit; nextMask++) {
                            int covered = 0;
                            for (int i = 0; i < n; i++) {
                                if (((1 << i) & currMask) == 0) {
                                    int up = i - 1;
                                    int down = i + 1;
                                    if (up >= 0 && ((1 << up) & currMask) != 0)
                                        covered |= 1 << i;
                                    if (down < n && ((1 << down) & currMask) != 0)
                                        covered |= 1 << i;
                                    if (((1 << i) & prevMask) != 0)
                                        covered |= 1 << i;
                                    if (((1 << i) & nextMask) != 0)
                                        covered |= 1 << i;
                                }
                            }
                            int cost = dp[prevMask][currMask] + n - Integer.bitCount(covered);
                            if (cost < nextStates[currMask][nextMask]) {
                                nextStates[currMask][nextMask] = cost;
                            }
                        }
                    }
                }
            }
            dp = nextStates;
        }

        int minCost = INFINITY;
        for (int[] row : dp) {
            for (int val : row) {
                if (val < minCost) {
                    minCost = val;
                }
            }
        }
        System.out.println(n * m - minCost);
    }
}
